-- ============================================================================
-- B5 FOLLOW-ON W2 (publish inputs in prompts and lessons): producedwater.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 1,
-- route (a), and the spec docs/graded-field-audit/w2/producedwater.json (the
-- inputs, where each came from, and the key each reproduces through the
-- vendored engines). Owner approved D1 to D7 as recommended, 2026-09-21.
--
-- BEGINNER
--   Prompt and lesson, no field moves. The lesson taught 141.5/(131.5 + API) x
--   999 thinned at 0.0007 per degree but never the reference temperature; the
--   engine uses 15.56 C, and the exact 60 F (15.5556 C) a learner would use
--   gives 862.321424, 0.0028 from the key against tol 1e-4 (B5). The prompt and
--   beginner m02 l04 now state 15.56 C, so the crude density is an exact hand
--   calculation. The other five beginner fields stay with the W4 panel mode.
--   PROMPT was: are the module's own declared choices, and nothing else is
--   looked up.
--   PROMPT now: are the module's own declared choices, and nothing else is
--   looked up. The crude chain takes a specific gravity at 60 F of 141.5 /
--   (131.5 + API) against the declared reference water of 999 kg/m3, thinned by
--   0.0007 per degree C above a reference temperature of 15.56 C.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected value and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after, so no answer grades
-- differently, nobody is re-scored and no attempts guard is needed.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) with its
-- live fields (exact jsonb), as production holds it after W1 (it is
-- rewritten), OR its W2 prompt with the same fields (left alone). Anything
-- else raises and the whole file rolls back. A file that will write first
-- checks the W1 post-state and refuses without it. Generated by
-- docs/graded-field-audit/w2_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- producedwater / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'producedwater' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w2 producedwater refused: producedwater/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '70df406a6e7bb7b2bb20ebf4682e27c5' and fields = '[{"key": "ogulagha_water_viscosity_pas", "tol": 1E-12, "unit": "Pa.s", "label": "The water viscosity at the stream temperature and salinity", "expected": 0.0005101915934473397}, {"key": "ogulagha_water_density_kgm3", "tol": 0.0001, "unit": "kg/m3", "label": "The brine density at the stream temperature and salinity", "expected": 1013.7286105037547}, {"key": "ogulagha_oil_density_kgm3", "tol": 0.0001, "unit": "kg/m3", "label": "The crude density at the stream temperature", "expected": 862.3241899811321}, {"key": "ogulagha_droplet_rise_ms", "tol": 1E-10, "unit": "m/s", "label": "The Stokes rise velocity of the median droplet", "expected": 0.0000782526023252317}, {"key": "ogulagha_basin_cut_micron", "tol": 0.000001, "unit": "micron", "label": "The API 421 basin cut size", "expected": 113.37669131197052}, {"key": "ogulagha_plate_cut_micron", "tol": 0.000001, "unit": "micron", "label": "The plate pack cut size", "expected": 69.84080434958841}]'::jsonb then 'old'
              when md5(prompt) = 'fd13e35a2c3be72561908ab04635a356' and fields = '[{"key": "ogulagha_water_viscosity_pas", "tol": 1E-12, "unit": "Pa.s", "label": "The water viscosity at the stream temperature and salinity", "expected": 0.0005101915934473397}, {"key": "ogulagha_water_density_kgm3", "tol": 0.0001, "unit": "kg/m3", "label": "The brine density at the stream temperature and salinity", "expected": 1013.7286105037547}, {"key": "ogulagha_oil_density_kgm3", "tol": 0.0001, "unit": "kg/m3", "label": "The crude density at the stream temperature", "expected": 862.3241899811321}, {"key": "ogulagha_droplet_rise_ms", "tol": 1E-10, "unit": "m/s", "label": "The Stokes rise velocity of the median droplet", "expected": 0.0000782526023252317}, {"key": "ogulagha_basin_cut_micron", "tol": 0.000001, "unit": "micron", "label": "The API 421 basin cut size", "expected": 113.37669131197052}, {"key": "ogulagha_plate_cut_micron", "tol": 0.000001, "unit": "micron", "label": "The plate pack cut size", "expected": 69.84080434958841}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'producedwater' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w2 producedwater refused: producedwater/beginner matches neither its published form (prompt md5 70df406a6e7bb7b2bb20ebf4682e27c5) nor its W2 form (prompt md5 fd13e35a2c3be72561908ab04635a356), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W2 form
  if v_s0 = 'new' then
    raise notice 'w2 producedwater: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024a/b) must be applied first: production holds it, and the W2
  -- apply script checks all 34 files; this reads two of its rows
  if exists (select 1 from public.academy_capstones where app_slug = 'integrity' and tier = 'beginner' and active and md5(prompt) <> '0e0ac66d6b97e9f7f66b5055e1fddf7d')
     or exists (select 1 from public.academy_capstones where app_slug = 'welldata' and tier = 'beginner' and active and md5(prompt) <> 'f362ed27e7d8766e7e51dcf1ca0e5e6e') then
    raise exception 'w2 producedwater refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'OGULAGHA, a gravity front end on a warm, moderately saline field. The water is 36000 bwpd, taken to m3/s with the exact barrel of 0.158987294928 m3, at 58.5 C and 42500 ppm of total dissolved solids, and the crude is 27.5 degrees API at the same temperature. The droplets arrive at 420 ppm with a volume median of 22 micron and a log spread sigma of 0.75. The basin is 15 m long, 3.4 m wide and 1.5 m deep, read at a short-circuit allowance F of 1.6. The plate pack is 48 plates of 2.5 m2 projected area each, with 0.7 of that area credited as settling. The water viscosity fit, the brine density fit and the crude density chain from API gravity are the module''s own declared choices, and nothing else is looked up. The crude chain takes a specific gravity at 60 F of 141.5 / (131.5 + API) against the declared reference water of 999 kg/m3, thinned by 0.0007 per degree C above a reference temperature of 15.56 C. Report six values: the water viscosity, the brine density, the crude density, the Stokes rise velocity of a droplet at the volume median, the basin cut size and the plate pack cut size. The viscosity in Pa.s and the rise velocity in m/s, to twelve decimals. The two densities in kg/m3 and the two cut sizes in micron, to six decimals.'
     where app_slug = 'producedwater' and tier = 'beginner' and active and md5(prompt) = '70df406a6e7bb7b2bb20ebf4682e27c5';
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w2 producedwater refused: producedwater/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'fd13e35a2c3be72561908ab04635a356' and fields = '[{"key": "ogulagha_water_viscosity_pas", "tol": 1E-12, "unit": "Pa.s", "label": "The water viscosity at the stream temperature and salinity", "expected": 0.0005101915934473397}, {"key": "ogulagha_water_density_kgm3", "tol": 0.0001, "unit": "kg/m3", "label": "The brine density at the stream temperature and salinity", "expected": 1013.7286105037547}, {"key": "ogulagha_oil_density_kgm3", "tol": 0.0001, "unit": "kg/m3", "label": "The crude density at the stream temperature", "expected": 862.3241899811321}, {"key": "ogulagha_droplet_rise_ms", "tol": 1E-10, "unit": "m/s", "label": "The Stokes rise velocity of the median droplet", "expected": 0.0000782526023252317}, {"key": "ogulagha_basin_cut_micron", "tol": 0.000001, "unit": "micron", "label": "The API 421 basin cut size", "expected": 113.37669131197052}, {"key": "ogulagha_plate_cut_micron", "tol": 0.000001, "unit": "micron", "label": "The plate pack cut size", "expected": 69.84080434958841}]'::jsonb) from public.academy_capstones where app_slug = 'producedwater' and tier = 'beginner' and active) is not true then
    raise exception 'w2 producedwater refused: producedwater/beginner does not read back as its W2 form';
  end if;

  raise notice 'w2 producedwater: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
